SELECT d.driverId, d.forename, d.surname, d.url
FROM drivers d
JOIN circuits c ON d.url = c.url;

SELECT DISTINCT d.driverId, d.forename, d.surname, d.url
FROM drivers d
JOIN circuits c ON d.url = c.url;

SELECT DISTINCT d.driverId, d.driverRef, d.number, d.code, d.forename, d.surname, d.dob, d.nationality, d.url
FROM drivers d
WHERE d.url IN (SELECT c.url FROM circuits c);

SELECT d.driverId, d.forename, d.surname, d.url
FROM drivers d
WHERE d.url IS NOT NULL AND d.url != '' AND d.url IN (SELECT url FROM circuits WHERE url IS NOT NULL AND url != '');

SELECT DISTINCT d.driverId, d.forename, d.surname, d.url
FROM drivers AS d
JOIN circuits AS c ON d.url = c.url;

SELECT d.driverId, d.forename, d.surname, d.url
FROM drivers AS d
WHERE d.url IN (SELECT c.url FROM circuits AS c WHERE c.url IS NOT NULL);
